192	    private ApiResponse dispatchRequest(ApiAction action, ApiRequest apiRequest, Session session) throws ApiException {
193	        switch (action) {
194	            case EXEC:
195	                return processExecRequest(apiRequest, session);
196	            case ASYNC_EXEC:
197	                return processAsyncExecRequest(apiRequest, session);
198	            case INTERRUPT_JOB:
199	                return processInterruptJob(apiRequest, session);
200	            case PULL_RESULTS:
201	                return processPullResultsRequest(apiRequest, session);
202	            case SESSION_INFO:
203	                return processSessionInfoRequest(apiRequest, session);
204	            case JOIN_SESSION:
205	                return processJoinSessionRequest(apiRequest, session);
206	            case CLOSE_SESSION:
207	                return processCloseSessionRequest(apiRequest, session);
208	            case INIT_SESSION:
209	                break;
210	        }
211	        return null;
212	    }
