/**
 * 对类进行通知增强 Created by vlinux on 15/5/17.
 * @author hengyunabc
 */
public class Enhancer implements ClassFileTransformer {

    private static final Logger logger = LoggerFactory.getLogger(Enhancer.class);

    private final AdviceListener listener;
    private final boolean isTracing;
    private final boolean skipJDKTrace;
    private final Matcher classNameMatcher;
    private final Matcher classNameExcludeMatcher;
    private final Matcher methodNameMatcher;
    /**
     * 指定增强的 classloader hash，如果为空则不限制。
     */
    private final String targetClassLoaderHash;
    private LineEnhanceOptions lineEnhanceOptions;
    private final EnhancerAffect affect;
    private Set<Class<?>> matchingClasses = null;
    private boolean isLazy = false;
    private static final ClassLoader selfClassLoader = Enhancer.class.getClassLoader();

    // 被增强的类的缓存
    private final static Map<Class<?>/* Class */, Object> classBytesCache = new WeakHashMap<Class<?>, Object>();
    private static SpyImpl spyImpl = new SpyImpl();

    static {
        SpyAPI.setSpy(spyImpl);
    }

    /**
     * @param listener                通知监听器
     * @param isTracing               可跟踪方法调用
     * @param skipJDKTrace            是否忽略对JDK内部方法的跟踪
     * @param classNameMatcher        类名匹配
     * @param classNameExcludeMatcher 排除的类名匹配
     * @param methodNameMatcher       方法名匹配
     */
    public Enhancer(AdviceListener listener, boolean isTracing, boolean skipJDKTrace, Matcher classNameMatcher,
            Matcher classNameExcludeMatcher,
            Matcher methodNameMatcher) {
        this(listener, isTracing, skipJDKTrace, classNameMatcher, classNameExcludeMatcher, methodNameMatcher, false, null);
    }

    /**
     * @param listener                通知监听器
     * @param isTracing               可跟踪方法调用
     * @param skipJDKTrace            是否忽略对JDK内部方法的跟踪
     * @param classNameMatcher        类名匹配
     * @param classNameExcludeMatcher 排除的类名匹配
     * @param methodNameMatcher       方法名匹配
     * @param isLazy                  是否懒加载模式
     */
    public Enhancer(AdviceListener listener, boolean isTracing, boolean skipJDKTrace, Matcher classNameMatcher,
            Matcher classNameExcludeMatcher,
            Matcher methodNameMatcher, boolean isLazy) {
        this(listener, isTracing, skipJDKTrace, classNameMatcher, classNameExcludeMatcher, methodNameMatcher, isLazy, null);
    }

    public Enhancer(AdviceListener listener, boolean isTracing, boolean skipJDKTrace, Matcher classNameMatcher,
            Matcher classNameExcludeMatcher,
            Matcher methodNameMatcher, boolean isLazy, String targetClassLoaderHash) {
        this.listener = listener;
        this.isTracing = isTracing;
        this.skipJDKTrace = skipJDKTrace;
        this.classNameMatcher = classNameMatcher;
        this.classNameExcludeMatcher = classNameExcludeMatcher;
        this.methodNameMatcher = methodNameMatcher;
        this.targetClassLoaderHash = targetClassLoaderHash;
        this.affect = new EnhancerAffect();
        affect.setListenerId(listener.id());
        this.isLazy = isLazy;
    }

    public void setLineEnhanceOptions(LineEnhanceOptions lineEnhanceOptions) {
        this.lineEnhanceOptions = lineEnhanceOptions;
    }

    @Override
    public byte[] transform(final ClassLoader inClassLoader, String className, Class<?> classBeingRedefined,
            ProtectionDomain protectionDomain, byte[] classfileBuffer) throws IllegalClassFormatException {
        try {
            // 检查classloader能否加载到 SpyAPI，如果不能，则放弃增强
            try {
                if (inClassLoader != null) {
                    inClassLoader.loadClass(SpyAPI.class.getName());
                }
            } catch (Throwable e) {
                logger.error("the classloader can not load SpyAPI, ignore it. classloader: {}, className: {}",
                        inClassLoader.getClass().getName(), className, e);
                return null;
            }

            // 这里要再次过滤一次，为啥？因为在transform的过程中，有可能还会再诞生新的类
            // 所以需要将之前需要转换的类集合传递下来，再次进行判断
            if (matchingClasses != null && !matchingClasses.contains(classBeingRedefined)) {
                // 懒加载模式：当类首次加载时（classBeingRedefined == null），检查类名是否匹配
                if (isLazy && classBeingRedefined == null && className != null) {
                    // 将 className 从 internal name 转换为 binary name
                    String classNameDot = className.replace('/', '.');
                    if (!classNameMatcher.matching(classNameDot)) {
                        return null;
                    }
                    // 检查是否被排除
                    if (classNameExcludeMatcher != null && classNameExcludeMatcher.matching(classNameDot)) {
                        return null;
                    }
                    // 检查 classloader 是否匹配（指定了 targetClassLoaderHash 时生效）
                    if (!isTargetClassLoader(inClassLoader)) {
                        return null;
                    }
                    // 检查是否是 arthas 自身的类
                    if (inClassLoader != null && isEquals(inClassLoader, selfClassLoader)) {
                        return null;
                    }
                    // 检查是否是 unsafe 类
                    if (!GlobalOptions.isUnsafe && inClassLoader == null) {
                        return null;
                    }
                    logger.info("Lazy mode: enhancing newly loaded class: {}", classNameDot);
                } else {
                    return null;
                }
            }

            //keep origin class reader for bytecode optimizations, avoiding JVM metaspace OOM.
            ClassNode classNode = new ClassNode(Opcodes.ASM9);
            ClassReader classReader = AsmUtils.toClassNode(classfileBuffer, classNode);
            // remove JSR https://github.com/alibaba/arthas/issues/1304
            classNode = AsmUtils.removeJSRInstructions(classNode);

            // 生成增强字节码
            DefaultInterceptorClassParser defaultInterceptorClassParser = new DefaultInterceptorClassParser();

            final List<InterceptorProcessor> interceptorProcessors = new ArrayList<InterceptorProcessor>();

            interceptorProcessors.addAll(defaultInterceptorClassParser.parse(SpyInterceptor1.class));
            interceptorProcessors.addAll(defaultInterceptorClassParser.parse(SpyInterceptor2.class));
            interceptorProcessors.addAll(defaultInterceptorClassParser.parse(SpyInterceptor3.class));

            final List<InterceptorProcessor> lineInterceptorProcessors = new ArrayList<InterceptorProcessor>();
            if (isLineEnhance()) {
                lineInterceptorProcessors.addAll(defaultInterceptorClassParser.parse(SpyLineInterceptor.class));
                for (InterceptorProcessor interceptorProcessor : lineInterceptorProcessors) {
                    interceptorProcessor.setLocationMatcher(new LineLocationMatcher(lineEnhanceOptions.getMode(),
                            lineEnhanceOptions.getDuplicatePolicy(), lineEnhanceOptions.getLineList()));
                }
            }

            if (this.isTracing) {
                if (!this.skipJDKTrace) {
                    interceptorProcessors.addAll(defaultInterceptorClassParser.parse(SpyTraceInterceptor1.class));
                    interceptorProcessors.addAll(defaultInterceptorClassParser.parse(SpyTraceInterceptor2.class));
                    interceptorProcessors.addAll(defaultInterceptorClassParser.parse(SpyTraceInterceptor3.class));
                } else {
                    interceptorProcessors.addAll(defaultInterceptorClassParser.parse(SpyTraceExcludeJDKInterceptor1.class));
                    interceptorProcessors.addAll(defaultInterceptorClassParser.parse(SpyTraceExcludeJDKInterceptor2.class));
                    interceptorProcessors.addAll(defaultInterceptorClassParser.parse(SpyTraceExcludeJDKInterceptor3.class));
                }
            }

            List<MethodNode> matchedMethods = new ArrayList<MethodNode>();
            for (MethodNode methodNode : classNode.methods) {
                if (isLineEnhance()) {
                    if (isLineMethodMatched(methodNode)) {
                        matchedMethods.add(methodNode);
                    }
                } else if (!isIgnore(methodNode, methodNameMatcher)) {
                    matchedMethods.add(methodNode);
                }
            }

            // https://github.com/alibaba/arthas/issues/1690
            if (AsmUtils.isEnhancerByCGLIB(className)) {
                for (MethodNode methodNode : matchedMethods) {
                    if (AsmUtils.isConstructor(methodNode)) {
                        AsmUtils.fixConstructorExceptionTable(methodNode);
                    }
                }
            }

            // 用于检查是否已插入了 spy函数，如果已有则不重复处理
            GroupLocationFilter groupLocationFilter = new GroupLocationFilter();

            LocationFilter enterFilter = new InvokeContainLocationFilter(Type.getInternalName(SpyAPI.class), "atEnter",
                    LocationType.ENTER);
            LocationFilter existFilter = new InvokeContainLocationFilter(Type.getInternalName(SpyAPI.class), "atExit",
                    LocationType.EXIT);
            LocationFilter exceptionFilter = new InvokeContainLocationFilter(Type.getInternalName(SpyAPI.class),
                    "atExceptionExit", LocationType.EXCEPTION_EXIT);

            groupLocationFilter.addFilter(enterFilter);
            groupLocationFilter.addFilter(existFilter);
            groupLocationFilter.addFilter(exceptionFilter);

            LocationFilter invokeBeforeFilter = new InvokeCheckLocationFilter(Type.getInternalName(SpyAPI.class),
                    "atBeforeInvoke", LocationType.INVOKE);
            LocationFilter invokeAfterFilter = new InvokeCheckLocationFilter(Type.getInternalName(SpyAPI.class),
                    "atInvokeException", LocationType.INVOKE_COMPLETED);
            LocationFilter invokeExceptionFilter = new InvokeCheckLocationFilter(Type.getInternalName(SpyAPI.class),
                    "atInvokeException", LocationType.INVOKE_EXCEPTION_EXIT);
            groupLocationFilter.addFilter(invokeBeforeFilter);
            groupLocationFilter.addFilter(invokeAfterFilter);
            groupLocationFilter.addFilter(invokeExceptionFilter);
            if (isLineEnhance()) {
                groupLocationFilter.addFilter(new LineAlreadyEnhancedLocationFilter(Type.getInternalName(SpyAPI.class),
                        "atLine"));
            }

            for (MethodNode methodNode : matchedMethods) {
                if (AsmUtils.isNative(methodNode)) {
                    logger.info("ignore native method: {}",
                            AsmUtils.methodDeclaration(Type.getObjectType(classNode.name), methodNode));
                    continue;
                }
                Set<Integer> lineNumbers = null;
                if (isLineEnhance()) {
                    lineNumbers = enhanceLineInterceptors(classNode, methodNode, groupLocationFilter,
                            lineInterceptorProcessors);
                    if (lineNumbers.isEmpty()) {
                        continue;
                    }
                }
                // 先查找是否有 atBeforeInvoke 函数，如果有，则说明已经有trace了，则直接不再尝试增强，直接插入 listener
                if(AsmUtils.containsMethodInsnNode(methodNode, Type.getInternalName(SpyAPI.class), "atBeforeInvoke")) {
                    for (AbstractInsnNode insnNode = methodNode.instructions.getFirst(); insnNode != null; insnNode = insnNode
                            .getNext()) {
                        if (insnNode instanceof MethodInsnNode) {
                            final MethodInsnNode methodInsnNode = (MethodInsnNode) insnNode;
                            if(this.skipJDKTrace) {
                                if(methodInsnNode.owner.startsWith("java/")) {
                                    continue;
                                }
                            }
                            // 原始类型的box类型相关的都跳过
                            if(AsmOpUtils.isBoxType(Type.getObjectType(methodInsnNode.owner))) {
                                continue;
                            }
                            AdviceListenerManager.registerTraceAdviceListener(inClassLoader, className,
                                    methodInsnNode.owner, methodInsnNode.name, methodInsnNode.desc, listener);
                        }
                    }
                }else {
                    MethodProcessor methodProcessor = new MethodProcessor(classNode, methodNode, groupLocationFilter);
                    for (InterceptorProcessor interceptor : interceptorProcessors) {
                        try {
                            List<Location> locations = interceptor.process(methodProcessor);
                            for (Location location : locations) {
                                if (location instanceof MethodInsnNodeWare) {
                                    MethodInsnNodeWare methodInsnNodeWare = (MethodInsnNodeWare) location;
                                    MethodInsnNode methodInsnNode = methodInsnNodeWare.methodInsnNode();

                                    AdviceListenerManager.registerTraceAdviceListener(inClassLoader, className,
                                            methodInsnNode.owner, methodInsnNode.name, methodInsnNode.desc, listener);
                                }
                            }

                        } catch (Throwable e) {
                            logger.error("enhancer error, class: {}, method: {}, interceptor: {}", classNode.name, methodNode.name, interceptor.getClass().getName(), e);
                        }
                    }
                }

                // enter/exist 总是要插入 listener
                AdviceListenerManager.registerAdviceListener(inClassLoader, className, methodNode.name, methodNode.desc,
                        listener);
                if (isLineEnhance()) {
                    for (Integer lineNumber : lineNumbers) {
                        AdviceListenerManager.registerLineAdviceListener(inClassLoader, className, methodNode.name,
                                methodNode.desc, lineNumber, listener);
                    }
                }
                affect.addMethodAndCount(inClassLoader, className, methodNode.name, methodNode.desc);
            }

            // https://github.com/alibaba/arthas/issues/1223 , V1_5 的major version是49
            if (AsmUtils.getMajorVersion(classNode.version) < 49) {
                classNode.version = AsmUtils.setMajorVersion(classNode.version, 49);
            }

            byte[] enhanceClassByteArray = AsmUtils.toBytes(classNode, inClassLoader, classReader);

            // 增强成功，记录类
            classBytesCache.put(classBeingRedefined, new Object());

            // dump the class
            dumpClassIfNecessary(className, enhanceClassByteArray, affect);

            // 成功计数
            affect.cCnt(1);

            return enhanceClassByteArray;
        } catch (Throwable t) {
            logger.warn("transform loader[{}]:class[{}] failed.", inClassLoader, className, t);
            affect.setThrowable(t);
        }

        return null;
    }

    /**
     * 是否抽象属性
     */
    private boolean isAbstract(int access) {
        return (Opcodes.ACC_ABSTRACT & access) == Opcodes.ACC_ABSTRACT;
    }

    /**
     * 是否需要忽略
     */
    private boolean isIgnore(MethodNode methodNode, Matcher methodNameMatcher) {
        return null == methodNode || isAbstract(methodNode.access) || !methodNameMatcher.matching(methodNode.name)
                || ArthasCheckUtils.isEquals(methodNode.name, "<clinit>");
    }

    private boolean isLineEnhance() {
        return lineEnhanceOptions != null && !lineEnhanceOptions.getLines().isEmpty();
    }

    private boolean isLineMethodMatched(MethodNode methodNode) {
        if (isIgnore(methodNode, methodNameMatcher)) {
            return false;
        }
        if (AsmUtils.isConstructor(methodNode) || AsmUtils.isNative(methodNode)) {
            return false;
        }
        String methodDesc = lineEnhanceOptions.getMethodDesc();
        if (methodDesc != null && methodDesc.length() > 0 && !methodDesc.equals(methodNode.desc)) {
            return false;
        }
        return hasAnyLine(methodNode, lineEnhanceOptions.getLines());
    }

    private boolean hasAnyLine(MethodNode methodNode, Set<Integer> targetLines) {
        return !matchedLineNumbers(methodNode, targetLines).isEmpty();
    }

    private Set<Integer> matchedLineNumbers(MethodNode methodNode, Set<Integer> targetLines) {
        Set<Integer> result = new LinkedHashSet<Integer>();
        if (methodNode == null || methodNode.instructions == null || targetLines == null || targetLines.isEmpty()) {
            return result;
        }
        for (AbstractInsnNode insnNode = methodNode.instructions.getFirst(); insnNode != null; insnNode = insnNode
                .getNext()) {
            if (insnNode instanceof LineNumberNode) {
                int line = ((LineNumberNode) insnNode).line;
                if (targetLines.contains(line)) {
                    result.add(line);
                }
            }
        }
        return result;
    }

    private Set<Integer> enhanceLineInterceptors(ClassNode classNode, MethodNode methodNode,
            GroupLocationFilter groupLocationFilter, List<InterceptorProcessor> lineInterceptorProcessors) {
        Set<Integer> lineNumbers = findAlreadyEnhancedLineNumbers(methodNode, lineEnhanceOptions.getLines());
        MethodProcessor methodProcessor = new MethodProcessor(classNode, methodNode, groupLocationFilter);
        for (InterceptorProcessor interceptor : lineInterceptorProcessors) {
            try {
                List<Location> locations = interceptor.process(methodProcessor);
                for (Location location : locations) {
                    if (location instanceof LineLocation) {
                        lineNumbers.add(((LineLocation) location).getTargetLine());
                    }
                }
            } catch (Throwable e) {
                logger.error("line enhancer error, class: {}, method: {}, interceptor: {}", classNode.name,
                        methodNode.name, interceptor.getClass().getName(), e);
            }
        }
        lineNumbers.addAll(findAlreadyEnhancedLineNumbers(methodNode, lineEnhanceOptions.getLines()));
        return lineNumbers;
    }

    private Set<Integer> findAlreadyEnhancedLineNumbers(MethodNode methodNode, Set<Integer> targetLines) {
        Set<Integer> result = new LinkedHashSet<Integer>();
        if (methodNode == null || methodNode.instructions == null) {
            return result;
        }
        for (AbstractInsnNode insnNode = methodNode.instructions.getFirst(); insnNode != null; insnNode = insnNode
                .getNext()) {
            if (insnNode instanceof LineNumberNode) {
                LineNumberNode lineNumberNode = (LineNumberNode) insnNode;
                if (targetLines.contains(lineNumberNode.line) && hasLineSpyAround(lineNumberNode)) {
                    result.add(lineNumberNode.line);
                }
            }
        }
        return result;
    }

    private static boolean hasLineSpyAround(AbstractInsnNode insnNode) {
        return LineAlreadyEnhancedLocationFilter.hasLineSpyAround(insnNode, Type.getInternalName(SpyAPI.class),
                "atLine");
    }

    private static class LineAlreadyEnhancedLocationFilter implements LocationFilter {
        private final String owner;
        private final String methodName;

        private LineAlreadyEnhancedLocationFilter(String owner, String methodName) {
            this.owner = owner;
            this.methodName = methodName;
        }

        @Override
        public boolean allow(AbstractInsnNode insnNode, LocationType locationType, boolean complete) {
            if (!LocationType.LINE.equals(locationType)) {
                return false;
            }
            return !hasLineSpyAround(insnNode, owner, methodName);
        }

        private static boolean hasLineSpyAround(AbstractInsnNode insnNode, String owner, String methodName) {
            AbstractInsnNode current = insnNode.getPrevious();
            while (current != null && !(current instanceof LineNumberNode)) {
                if (isMethodInsn(current, owner, methodName)) {
                    return true;
                }
                current = current.getPrevious();
            }
            current = insnNode.getNext();
            while (current != null && !(current instanceof LineNumberNode)) {
                if (isMethodInsn(current, owner, methodName)) {
                    return true;
                }
                current = current.getNext();
            }
            return false;
        }

        private static boolean isMethodInsn(AbstractInsnNode insnNode, String owner, String methodName) {
            if (insnNode instanceof MethodInsnNode) {
                MethodInsnNode methodInsnNode = (MethodInsnNode) insnNode;
                return owner.equals(methodInsnNode.owner) && methodName.equals(methodInsnNode.name);
            }
            return false;
        }
    }

    /**
     * dump class to file
     */
    private static void dumpClassIfNecessary(String className, byte[] data, EnhancerAffect affect) {
        if (!GlobalOptions.isDump) {
            return;
        }
        final File dumpClassFile = new File("./arthas-class-dump/" + className + ".class");
        final File classPath = new File(dumpClassFile.getParent());

        // 创建类所在的包路径
        if (!classPath.mkdirs() && !classPath.exists()) {
            logger.warn("create dump classpath:{} failed.", classPath);
            return;
        }

        // 将类字节码写入文件
        try {
            FileUtils.writeByteArrayToFile(dumpClassFile, data);
            affect.addClassDumpFile(dumpClassFile);
            if (GlobalOptions.verbose) {
                logger.info("dump enhanced class: {}, path: {}", className, dumpClassFile);
            }
        } catch (IOException e) {
            logger.warn("dump class:{} to file {} failed.", className, dumpClassFile, e);
        }

    }

    /**
     * 是否需要过滤的类
     *
     * @param classes 类集合
     */
    private List<Pair<Class<?>, String>> filter(Set<Class<?>> classes) {
        List<Pair<Class<?>, String>> filteredClasses = new ArrayList<Pair<Class<?>, String>>();
        final Iterator<Class<?>> it = classes.iterator();
        while (it.hasNext()) {
            final Class<?> clazz = it.next();
            boolean removeFlag = false;
            if (null == clazz) {
                removeFlag = true;
            } else if (!isTargetClassLoader(clazz.getClassLoader())) {
                filteredClasses.add(new Pair<Class<?>, String>(clazz, "classloader is not matched"));
                removeFlag = true;
            } else if (isSelf(clazz)) {
                filteredClasses.add(new Pair<Class<?>, String>(clazz, "class loaded by arthas itself"));
                removeFlag = true;
            } else if (isUnsafeClass(clazz)) {
                filteredClasses.add(new Pair<Class<?>, String>(clazz, "class loaded by Bootstrap Classloader, try to execute `options unsafe true`"));
                removeFlag = true;
            } else if (isExclude(clazz)) {
                filteredClasses.add(new Pair<Class<?>, String>(clazz, "class is excluded"));
                removeFlag = true;
            } else {
                Pair<Boolean, String> unsupportedResult = isUnsupportedClass(clazz);
                if (unsupportedResult.getFirst()) {
                    filteredClasses.add(new Pair<Class<?>, String>(clazz, unsupportedResult.getSecond()));
                    removeFlag = true;
                }
            }
            if (removeFlag) {
                it.remove();
            }
        }
        return filteredClasses;
    }

    private boolean isExclude(Class<?> clazz) {
        if (this.classNameExcludeMatcher != null) {
            return classNameExcludeMatcher.matching(clazz.getName());
        }
        return false;
    }

    /**
     * 是否过滤Arthas加载的类
     */
    private static boolean isSelf(Class<?> clazz) {
        return null != clazz && isEquals(clazz.getClassLoader(), selfClassLoader);
    }

    /**
     * 是否过滤unsafe类
     */
    private static boolean isUnsafeClass(Class<?> clazz) {
        return !GlobalOptions.isUnsafe && clazz.getClassLoader() == null;
    }

    /**
     * 是否过滤目前暂不支持的类
     */
    private static Pair<Boolean, String> isUnsupportedClass(Class<?> clazz) {
        if (ClassUtils.isLambdaClass(clazz)) {
            return new Pair<Boolean, String>(Boolean.TRUE, "class is lambda");
        }

        if (clazz.isInterface() && !GlobalOptions.isSupportDefaultMethod) {
            return new Pair<Boolean, String>(Boolean.TRUE, "class is interface");
        }

        if (clazz.equals(Integer.class)) {
            return new Pair<Boolean, String>(Boolean.TRUE, "class is java.lang.Integer");
        }

        if (clazz.equals(Class.class)) {
            return new Pair<Boolean, String>(Boolean.TRUE, "class is java.lang.Class");
        }

        if (clazz.equals(Method.class)) {
            return new Pair<Boolean, String>(Boolean.TRUE, "class is java.lang.Method");
        }

        if (clazz.isArray()) {
            return new Pair<Boolean, String>(Boolean.TRUE, "class is array");
        }
        return new Pair<Boolean, String>(Boolean.FALSE, "");
    }

    /**
     * 对象增强
     *
     * @param inst              inst
     * @param maxNumOfMatchedClass 匹配的class最大数量
     * @return 增强影响范围
     * @throws UnmodifiableClassException 增强失败
     */
    public synchronized EnhancerAffect enhance(final Instrumentation inst, int maxNumOfMatchedClass) throws UnmodifiableClassException {
        // 获取需要增强的类集合
        this.matchingClasses = GlobalOptions.isDisableSubClass
                ? SearchUtils.searchClass(inst, classNameMatcher)
                : SearchUtils.searchSubClass(inst, SearchUtils.searchClass(inst, classNameMatcher));

        // 过滤掉无法被增强的类
        List<Pair<Class<?>, String>> filtedList = filter(matchingClasses);
        if (!filtedList.isEmpty()) {
            for (Pair<Class<?>, String> filted : filtedList) {
                logger.info("ignore class: {}, reason: {}", filted.getFirst().getName(), filted.getSecond());
            }
        }

        if (matchingClasses.size() > maxNumOfMatchedClass) {
            affect.setOverLimitMsg("The number of matched classes is " +matchingClasses.size()+ ", greater than the limit value " + maxNumOfMatchedClass + ". Try to change the limit with option '-m <arg>'.");
            return affect;
        }

        logger.info("enhance matched classes: {}", matchingClasses);

        affect.setTransformer(this);

        try {
            ArthasBootstrap.getInstance().getTransformerManager().addTransformer(this, isTracing);

            // 懒加载模式：同时添加到懒加载 transformer 列表
            // 这样才能在类首次加载时被增强
            if (isLazy) {
                ArthasBootstrap.getInstance().getTransformerManager().addLazyTransformer(this);
                logger.info("Lazy mode enabled, transformer added to lazy transformer list");
            }

            // 批量增强
            if (GlobalOptions.isBatchReTransform) {
                final int size = matchingClasses.size();
                final Class<?>[] classArray = new Class<?>[size];
                arraycopy(matchingClasses.toArray(), 0, classArray, 0, size);
                if (classArray.length > 0) {
                    inst.retransformClasses(classArray);
                    logger.info("Success to batch transform classes: " + Arrays.toString(classArray));
                }
            } else {
                // for each 增强
                for (Class<?> clazz : matchingClasses) {
                    try {
                        inst.retransformClasses(clazz);
                        logger.info("Success to transform class: " + clazz);
                    } catch (Throwable t) {
                        logger.warn("retransform {} failed.", clazz, t);
                        if (t instanceof UnmodifiableClassException) {
                            throw (UnmodifiableClassException) t;
                        } else if (t instanceof RuntimeException) {
                            throw (RuntimeException) t;
                        } else {
                            throw new RuntimeException(t);
                        }
                    }
                }
            }
        } catch (Throwable e) {
            logger.error("Enhancer error, matchingClasses: {}", matchingClasses, e);
            affect.setThrowable(e);
        }

        return affect;
    }

    private boolean isTargetClassLoader(ClassLoader inClassLoader) {
        if (targetClassLoaderHash == null || targetClassLoaderHash.isEmpty()) {
            return true;
        }
        if (inClassLoader == null) {
            return false;
        }
        return Integer.toHexString(inClassLoader.hashCode()).equalsIgnoreCase(targetClassLoaderHash);
    }

    /**
     * 重置指定的Class
     *
     * @param inst             inst
     * @param classNameMatcher 类名匹配
     * @return 增强影响范围
     * @throws UnmodifiableClassException
     */
    public static synchronized EnhancerAffect reset(final Instrumentation inst, final Matcher classNameMatcher)
            throws UnmodifiableClassException {

        final EnhancerAffect affect = new EnhancerAffect();
        final Set<Class<?>> enhanceClassSet = new HashSet<Class<?>>();

        for (Class<?> classInCache : classBytesCache.keySet()) {
            if (classNameMatcher.matching(classInCache.getName())) {
                enhanceClassSet.add(classInCache);
            }
        }

        try {
            enhance(inst, enhanceClassSet);
            logger.info("Success to reset classes: " + enhanceClassSet);
        } finally {
            for (Class<?> resetClass : enhanceClassSet) {
                classBytesCache.remove(resetClass);
                affect.cCnt(1);
            }
        }

        return affect;
    }

    // 批量增强
    private static void enhance(Instrumentation inst, Set<Class<?>> classes)
            throws UnmodifiableClassException {
        int size = classes.size();
        Class<?>[] classArray = new Class<?>[size];
        arraycopy(classes.toArray(), 0, classArray, 0, size);
        if (classArray.length > 0) {
            inst.retransformClasses(classArray);
        }
    }
}

package com.taobao.arthas.core.command.monitor200;

import java.lang.instrument.Instrumentation;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

import com.alibaba.bytekit.utils.AsmUtils;
import com.alibaba.deps.org.objectweb.asm.Opcodes;
import com.alibaba.deps.org.objectweb.asm.tree.AbstractInsnNode;
import com.alibaba.deps.org.objectweb.asm.tree.ClassNode;
import com.alibaba.deps.org.objectweb.asm.tree.LineNumberNode;
import com.alibaba.deps.org.objectweb.asm.tree.MethodNode;
import com.taobao.arthas.core.GlobalOptions;
import com.taobao.arthas.core.advisor.AdviceListener;
import com.taobao.arthas.core.advisor.LineEnhanceOptions;
import com.taobao.arthas.core.command.Constants;
import com.taobao.arthas.core.command.model.LineListModel;
import com.taobao.arthas.core.shell.command.CommandProcess;
import com.taobao.arthas.core.util.SearchUtils;
import com.taobao.arthas.core.util.StringUtils;
import com.taobao.arthas.core.util.matcher.Matcher;
import com.taobao.arthas.core.view.ObjectView;
import com.taobao.middleware.cli.annotations.DefaultValue;
import com.taobao.middleware.cli.annotations.Description;
import com.taobao.middleware.cli.annotations.Name;
import com.taobao.middleware.cli.annotations.Option;
import com.taobao.middleware.cli.annotations.Summary;

@Name("line")
@Summary("Watch local variables and expression result at specified source line numbers")
@Description(Constants.EXPRESS_DESCRIPTION + "\nExamples:\n" +
        "  line --class demo.MathGame --line 51\n" +
        "  line --class demo.MathGame --line 51,56 --express '{params, localVarMap}'\n" +
        "  line --class demo.MathGame --method primeFactors --line 51 --condition 'localVarMap[\"i\"] > 10'\n" +
        "  line --class demo.MathGame --method primeFactors --desc '(I)Ljava/util/List;' --line 51\n" +
        "  line --list-lines --class demo.MathGame\n")
public class LineCommand extends EnhancerCommand {
    static final int MAX_LINE_COUNT = 256;
    static final int MAX_STACK_DEPTH = 256;
    static final String DEFAULT_EXPRESS = "{params, localVarMap}";

    private String classPattern;
    private String methodPattern;
    private String methodDesc;
    private List<String> lineSpecs;
    private Set<Integer> lineNumbers;
    private String express = DEFAULT_EXPRESS;
    private String conditionExpress;
    private boolean listLines;
    private boolean isRegEx;
    private Integer expand = 1;
    private Integer sizeLimit;
    private int numberOfLimit = 100;
    private boolean stack;
    private int stackDepth = 32;

    @Option(longName = "class")
    @Description("The full qualified class name you want to watch")
    public void setClassPattern(String classPattern) {
        this.classPattern = StringUtils.normalizeClassName(classPattern);
    }

    @Option(longName = "method")
    @Description("The method name you want to watch, optional")
    public void setMethodPattern(String methodPattern) {
        this.methodPattern = methodPattern;
    }

    @Option(longName = "desc")
    @Description("The JVM method descriptor, optional")
    public void setMethodDesc(String methodDesc) {
        this.methodDesc = methodDesc;
    }

    @Option(longName = "line", acceptMultipleValues = true)
    @Description("Source line numbers, supports comma separated values and repeated options")
    public void setLineSpecs(List<String> lineSpecs) {
        this.lineSpecs = lineSpecs;
    }

    @Option(longName = "express")
    @DefaultValue(DEFAULT_EXPRESS)
    @Description("The content you want to watch, written by ognl. Default value is '{params, localVarMap}'")
    public void setExpress(String express) {
        this.express = express;
    }

    @Option(longName = "condition")
    @Description(Constants.CONDITION_EXPRESS)
    public void setConditionExpress(String conditionExpress) {
        this.conditionExpress = conditionExpress;
    }

    @Option(longName = "list-lines", flag = true)
    @Description("List available line numbers from LineNumberTable without enhancing classes")
    public void setListLines(boolean listLines) {
        this.listLines = listLines;
    }

    @Option(shortName = "E", longName = "regex", flag = true)
    @Description("Enable regular expression to match (wildcard matching by default)")
    public void setRegEx(boolean regEx) {
        isRegEx = regEx;
    }

    @Option(shortName = "x", longName = "expand")
    @Description("Expand level of object (1 by default), the max value is " + ObjectView.MAX_DEEP)
    public void setExpand(Integer expand) {
        this.expand = expand;
    }

    @Option(shortName = "M", longName = "sizeLimit")
    @Description("Upper size limit in bytes for the result (must be greater than 0, default value comes from options object-size-limit)")
    public void setSizeLimit(Integer sizeLimit) {
        this.sizeLimit = sizeLimit;
    }

    @Option(shortName = "n", longName = "limits")
    @Description("Threshold of execution times")
    public void setNumberOfLimit(int numberOfLimit) {
        this.numberOfLimit = numberOfLimit;
    }

    @Option(longName = "stack", flag = true)
    @Description("Print current stack trace when line probe hits")
    public void setStack(boolean stack) {
        this.stack = stack;
    }

    @Option(longName = "stack-depth")
    @DefaultValue("32")
    @Description("Stack trace depth when --stack is enabled")
    public void setStackDepth(int stackDepth) {
        this.stackDepth = stackDepth;
    }

    @Override
    @Option(shortName = "c", longName = "classloader")
    @Description("The hash code of the special class's classLoader")
    public void setHashCode(String hashCode) {
        super.setHashCode(hashCode);
    }

    public String getClassPattern() {
        return classPattern;
    }

    public String getMethodPattern() {
        return methodPattern;
    }

    public String getMethodDesc() {
        return methodDesc;
    }

    public String getExpress() {
        return express;
    }

    public String getConditionExpress() {
        return conditionExpress;
    }

    public Integer getExpand() {
        return expand;
    }

    public Integer getSizeLimit() {
        return sizeLimit;
    }

    public int getNumberOfLimit() {
        return numberOfLimit;
    }

    public boolean isStack() {
        return stack;
    }

    public int getStackDepth() {
        return stackDepth;
    }

    public boolean isRegEx() {
        return isRegEx;
    }

    @Override
    public void process(CommandProcess process) {
        String validateError = validate();
        if (validateError != null) {
            process.end(-1, validateError);
            return;
        }
        if (listLines) {
            listLines(process);
            return;
        }
        super.process(process);
    }

    @Override
    protected Matcher getClassNameMatcher() {
        if (classNameMatcher == null) {
            classNameMatcher = SearchUtils.classNameMatcher(getClassPattern(), isRegEx());
        }
        return classNameMatcher;
    }

    @Override
    protected Matcher getClassNameExcludeMatcher() {
        if (classNameExcludeMatcher == null && getExcludeClassPattern() != null) {
            classNameExcludeMatcher = SearchUtils.classNameMatcher(getExcludeClassPattern(), isRegEx());
        }
        return classNameExcludeMatcher;
    }

    @Override
    protected Matcher getMethodNameMatcher() {
        if (methodNameMatcher == null) {
            methodNameMatcher = SearchUtils.classNameMatcher(getMethodPattern(), isRegEx());
        }
        return methodNameMatcher;
    }

    @Override
    protected AdviceListener getAdviceListener(CommandProcess process) {
        return new LineCommandAdviceListener(this, process, GlobalOptions.verbose || this.verbose);
    }

    @Override
    protected LineEnhanceOptions getLineEnhanceOptions() {
        return new LineEnhanceOptions(lineNumbers, methodDesc);
    }

    private String validate() {
        if (StringUtils.isEmpty(classPattern)) {
            return "The --class option is required.";
        }
        if (StringUtils.isEmpty(express)) {
            return "The --express option must not be empty.";
        }
        if (methodDesc != null && !methodDesc.startsWith("(")) {
            return "The --desc option must be a JVM method descriptor, for example '(I)V'.";
        }
        if (!listLines) {
            try {
                lineNumbers = parseLines(lineSpecs);
            } catch (IllegalArgumentException e) {
                return e.getMessage();
            }
        }
        if (expand == null || expand < 0 || expand > ObjectView.MAX_DEEP) {
            return "expand must be between 0 and " + ObjectView.MAX_DEEP + ".";
        }
        String sizeLimitError = WatchCommand.validateSizeLimit(sizeLimit);
        if (sizeLimitError != null) {
            return sizeLimitError;
        }
        if (numberOfLimit <= 0) {
            return "limits must be greater than 0.";
        }
        if (stackDepth <= 0 || stackDepth > MAX_STACK_DEPTH) {
            return "stack-depth must be between 1 and " + MAX_STACK_DEPTH + ".";
        }
        return null;
    }

    static Set<Integer> parseLines(List<String> lineSpecs) {
        if (lineSpecs == null || lineSpecs.isEmpty()) {
            throw new IllegalArgumentException("The --line option is required unless --list-lines is used.");
        }
        Set<Integer> result = new LinkedHashSet<Integer>();
        for (String lineSpec : lineSpecs) {
            if (StringUtils.isEmpty(lineSpec)) {
                continue;
            }
            String[] parts = lineSpec.split(",");
            for (String part : parts) {
                String value = part.trim();
                if (value.length() == 0) {
                    continue;
                }
                if (value.indexOf('-') >= 0) {
                    throw new IllegalArgumentException("Line range syntax is not supported in the first version: "
                            + value);
                }
                final int lineNumber;
                try {
                    lineNumber = Integer.parseInt(value);
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid line number: " + value);
                }
                if (lineNumber <= 0) {
                    throw new IllegalArgumentException("Line number must be greater than 0: " + value);
                }
                result.add(lineNumber);
                if (result.size() > MAX_LINE_COUNT) {
                    throw new IllegalArgumentException("Too many line numbers, maximum is " + MAX_LINE_COUNT + ".");
                }
            }
        }
        if (result.isEmpty()) {
            throw new IllegalArgumentException("The --line option is required unless --list-lines is used.");
        }
        return result;
    }

    private void listLines(CommandProcess process) {
        try {
            Instrumentation instrumentation = process.session().getInstrumentation();
            Set<Class<?>> classes = GlobalOptions.isDisableSubClass
                    ? SearchUtils.searchClass(instrumentation, getClassNameMatcher())
                    : SearchUtils.searchSubClass(instrumentation, SearchUtils.searchClass(instrumentation,
                            getClassNameMatcher()));
            if (classes.size() > maxNumOfMatchedClass) {
                process.end(-1, "The number of matched classes is " + classes.size()
                        + ", greater than the limit value " + maxNumOfMatchedClass
                        + ". Try to change the limit with option '-m <arg>'.");
                return;
            }
            int count = 0;
            for (Class<?> clazz : classes) {
                if (!isListableClass(clazz)) {
                    continue;
                }
                count += appendLineListModels(process, clazz);
            }
            if (count == 0) {
                process.end(-1, "No available line number is found.");
                return;
            }
            process.end();
        } catch (Throwable e) {
            process.end(-1, "list line numbers failed: " + e.getMessage());
        }
    }

    private boolean isListableClass(Class<?> clazz) {
        if (clazz == null) {
            return false;
        }
        if (hashCode != null && (clazz.getClassLoader() == null
                || !Integer.toHexString(clazz.getClassLoader().hashCode()).equalsIgnoreCase(hashCode))) {
            return false;
        }
        if (clazz.getClassLoader() == LineCommand.class.getClassLoader()) {
            return false;
        }
        if (!GlobalOptions.isUnsafe && clazz.getClassLoader() == null) {
            return false;
        }
        return getClassNameExcludeMatcher() == null || !getClassNameExcludeMatcher().matching(clazz.getName());
    }

    private int appendLineListModels(CommandProcess process, Class<?> clazz) throws Exception {
        ClassNode classNode = AsmUtils.loadClass(clazz);
        int count = 0;
        for (MethodNode methodNode : classNode.methods) {
            if (!isListLineMethodMatched(methodNode)) {
                continue;
            }
            List<Integer> lines = collectLines(methodNode);
            if (lines.isEmpty()) {
                continue;
            }
            LineListModel model = new LineListModel();
            model.setClassName(clazz.getName());
            model.setSourceFile(classNode.sourceFile);
            model.setMethodName(methodNode.name);
            model.setMethodDesc(methodNode.desc);
            model.setLines(lines);
            process.appendResult(model);
            count++;
        }
        return count;
    }

    private boolean isListLineMethodMatched(MethodNode methodNode) {
        if (methodNode == null || (methodNode.access & Opcodes.ACC_ABSTRACT) == Opcodes.ACC_ABSTRACT
                || (methodNode.access & Opcodes.ACC_NATIVE) == Opcodes.ACC_NATIVE) {
            return false;
        }
        if ("<clinit>".equals(methodNode.name) || "<init>".equals(methodNode.name)) {
            return false;
        }
        if (!getMethodNameMatcher().matching(methodNode.name)) {
            return false;
        }
        return methodDesc == null || methodDesc.length() == 0 || methodDesc.equals(methodNode.desc);
    }

    private List<Integer> collectLines(MethodNode methodNode) {
        Set<Integer> lines = new LinkedHashSet<Integer>();
        for (AbstractInsnNode insnNode = methodNode.instructions.getFirst(); insnNode != null; insnNode = insnNode
                .getNext()) {
            if (insnNode instanceof LineNumberNode) {
                lines.add(((LineNumberNode) insnNode).line);
            }
        }
        List<Integer> result = new ArrayList<Integer>(lines);
        Collections.sort(result);
        return result;
    }
}

